int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long coins;
    cin >> n >> coins;
    vector<long long> prices(n);
    for (int i = 0; i < n; i++) cin >> prices[i];

    sort(prices.begin(), prices.end());
    long long bought = 0;
    for (long long p : prices) {
        if (p > coins) break;
        coins -= p;
        bought++;
    }
    cout << bought << "\n";

    return 0;
}

